\begin{itemchoice}
			\itemch Ta có $A=(-7;5]$ và $B=(-1;+\infty)$. Mệnh đề $B=[-1;+\infty)$ là sai.
			\itemch $A\cap B = (-7;5] \cap (-1;+\infty) = (-1;5]$. Mệnh đề đúng.
			\itemch $A\cup B = (-7;5] \cup (-1;+\infty) = (-7;+\infty)$. Mệnh đề sai vì dùng ngoặc vuông $[-7$.
			\itemch $C_{\mathbb{R}}(A\cup B) = \mathbb{R} \setminus (-7;+\infty) = (-\infty;-7]$. Mệnh đề đúng.
		\end{itemchoice}
